var t=`0727-peanut-fish-stew-with-plantain`;var n=`world-0727`;var a=`GQ`;var s=`central-africa`;var r=4;var o=65;var l={en:`Peanut Fish Stew with Plantain`,ua:`Риба в арахісовому соусі з плантаном`};var g={en:`Peanut Fish Stew with Plantain is a Equatorial Guinea classic prepared with tilapia, lemon juice, garlic, yellow onion. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Риба в арахісовому соусі з плантаном, страва кухні країни Екваторіальна Гвінея зі складниками: тилапія, лимонний сік, часник, жовта цибуля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 20 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 20 хвилин.`,t:[`marinating`],m:20,i:[[`tilapia`,760,`g`],[`lemon-juice`,40,`ml`],[`garlic`,4,`clove`],[`ground-cumin`,5,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`tomato`,310,`g`],[`peanut-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 30 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 30 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:30,i:[[`peanut-butter`,180,`g`],[`water`,600,`ml`],[`plantain`,380,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`]]}];var h={slug:t,id:n,country:`GQ`,region:s,servings:4,minutes:65,title:l,text:g,steps:u};export{a as country,h as default,n as id,o as minutes,s as region,r as servings,t as slug,u as steps,g as text,l as title};